void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize pixel coordinates to [-1, 1]
    vec2 p = (fragCoord.xy - iResolution.xy * 0.5) / iResolution.y;

    // Square "radius" for the square tunnel
    float r = max(abs(p.x), abs(p.y)); // Square-like distance metric

    // Depth animation for the tunnel
    float speed = 0.5;
    float depth = mod(1.0 / r + iTime * speed, 1.0);

    // Initialize texture UV coordinates
    vec2 uv;

// Determine the active face of the square tunnel
    if (abs(p.x) > abs(p.y)) {
        // Left or right faces
        if (p.x > 0.0) {
            // Right face
            uv.x = (p.y + 1.0) * 0.5;  // Map y-coordinate to [0, 1]
            uv.y = depth;             // Map depth to y-axis
        } else {
            // Left face
            uv.x = (1.0 - p.y) * 0.5; // Flip y-coordinate for left face
            uv.y = depth;             // Map depth to y-axis
        }
    } else {
        // Top or bottom faces
        if (p.y > 0.0) {
            // Top face
            uv.x = (p.x + 1.0) * 0.5;  // Map x-coordinate to [0, 1]
            uv.y = 1.- depth;              // Map depth to y-axis
        } else {
            // Bottom face
            uv.x = (p.x + 1.0) * 0.5;  // Map x-coordinate to [0, 1]
            uv.y = depth;        // Flip depth for bottom face
        }
    }

    // Sample the video texture
    vec4 tex = texture(iChannel0, uv);

    // Darken the texture based on distance for lighting
    float dist = length(p);
    vec3 col = tex.rgb * (dist*2.);

    // Output the final color
    fragColor = vec4(col, 1.0);
}
